"""python -m notbydefault init|show|install|check|label"""
from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

from notbydefault import PACKAGE_DIR
from notbydefault.graph import Graph, db_path

# (answer key, node type, question, label template)
QUESTIONS = [
    ("goal", "goal", "What are you building? (the goal)", "{}"),
    ("users", "requirement", "Expected users? (e.g. 500 monthly actives)", "Expected users: {}"),
    ("budget", "constraint", "Monthly budget for infrastructure? (e.g. $50)", "Monthly budget: {}"),
    ("region", "constraint", "Region / compliance needs? (e.g. EU data residency, HIPAA)",
     "Region/compliance: {}"),
    ("team", "constraint", "Team size?", "Team size: {}"),
]


def _ask(question: str) -> str:
    try:
        return input(f"{question} [Enter to skip]: ").strip()
    except EOFError:
        return ""


def cmd_init(args) -> int:
    project = Path(args.project_dir).resolve()
    with Graph.for_project(project) as g:
        previous = [n["id"] for n in g.nodes() if n["data"].get("source") == "init"]
        if previous and not args.force:
            print(f"{project} is already initialised ({len(previous)} answers stored). "
                  "Use --force to replace them.")
            return 1
        g.delete_nodes(previous)

        answers = {}
        for key, _type, question, _label in QUESTIONS:
            given = getattr(args, key)
            answers[key] = given if given is not None else ("" if args.no_input else _ask(question))

        goal_id = None
        created = []
        for key, node_type, _question, label in QUESTIONS:
            value = answers[key].strip()
            if not value:
                continue
            nid = g.add_node(node_type, label.format(value), {"source": "init", "key": key,
                                                              "value": value})
            created.append(nid)
            if node_type == "goal":
                goal_id = nid
        if goal_id:
            for nid in created:
                if g.get_node(nid)["type"] == "requirement":
                    g.add_edge(nid, goal_id, "serves")

    print(f"Stored {len(created)} answer(s) in {db_path(project)}")
    return 0


def _describe(node: dict) -> str:
    d = node["data"]
    if node["type"] == "decision":
        extra = f"  [{d.get('kind')}/{d.get('category')}, {d.get('status')}]"
        if d.get("evidence"):
            extra += f"  from {d.get('source')}: {d['evidence']}"
        return f"{node['label']}{extra}"
    return node["label"]


def cmd_show(args) -> int:
    project = Path(args.project_dir).resolve()
    if not db_path(project).exists():
        print(f"No graph yet at {db_path(project)}. Run `init` first.")
        return 1
    with Graph.for_project(project) as g:
        nodes = g.nodes()
        by_id = {n["id"]: n for n in nodes}
        print(f"Decision Graph: {db_path(project)}")
        print(f"\nNodes ({len(nodes)})")
        for node_type in ("goal", "requirement", "constraint", "decision", "evidence",
                          "alternative", "code", "pivot"):
            group = [n for n in nodes if n["type"] == node_type]
            if not group:
                continue
            print(f"  {node_type}")
            for n in group:
                print(f"    #{n['id']:<4} {_describe(n)}")
        edges = g.edges()
        print(f"\nEdges ({len(edges)})")
        for e in edges:
            src, dst = by_id[e["src"]], by_id[e["dst"]]
            print(f"  #{src['id']} {src['label']}  --{e['type']}-->  #{dst['id']} {dst['label']}")
    return 0


def cmd_check(args) -> int:
    project = Path(args.project).resolve()
    if not db_path(project).exists():
        print(f"No graph at {db_path(project)}. Run this from the project dir or pass --project.")
        return 1
    from notbydefault.fit.run import CheckOptions, check_model_decision
    opts = CheckOptions(max_cost=args.max_cost, yes=args.yes,
                        calls_per_user=args.calls_per_user, n_samples=args.samples,
                        expand_rounds=args.expand_rounds)
    return check_model_decision(project, args.decision_id, opts)


def cmd_label(args) -> int:
    from notbydefault.fit.labels import label
    return label(Path(args.project).resolve(), args.decision_id, n=args.n)


def cmd_require(args) -> int:
    from notbydefault.stale import require
    return require(Path(args.project_dir), args.requirement)


def cmd_pivot(args) -> int:
    """List pivots, or record the user's choice for one by hand."""
    from notbydefault.pivot import resolve
    project = Path(args.project).resolve()
    if not db_path(project).exists():
        print(f"No graph at {db_path(project)}.")
        return 1
    with Graph.for_project(project) as g:
        if args.pivot_id is None:
            for p in g.nodes("pivot"):
                d = p["data"]
                print(f"#{p['id']:<4} [{d.get('status')}] {p['label']}  decisions: "
                      f"{', '.join(f'#{x}' for x in d.get('decisions', [])) or '-'}")
            return 0
        p = g.get_node(args.pivot_id)
        if not p or p["type"] != "pivot":
            print(f"No pivot #{args.pivot_id}")
            return 1
        if not args.choice:
            print(f"#{p['id']} [{p['data'].get('status')}] {p['label']}")
            return 0
        stale = resolve(g, p, args.choice, "(recorded with `notbydefault pivot`)")
    print(f"Pivot #{args.pivot_id}: {args.choice}"
          + (f"; decisions now stale: {', '.join(f'#{d}' for d in stale)}" if stale else ""))
    return 0


# --- install --------------------------------------------------------------------

HOOK_MARKER = "notbydefault"
PRE_TOOL_MATCHER = "Bash|PowerShell|Write|Edit|MultiEdit"


# event -> (hook script, matcher or None, timeout s). UserPromptSubmit has no matcher support,
# and its timeout covers one fast Groq call when the pre-filter matches.
OUR_HOOKS = {
    "PreToolUse": ("pre_tool.py", PRE_TOOL_MATCHER, 10),
    "UserPromptSubmit": ("user_prompt.py", None, 20),
}


def hook_entry(project: Path, script: str = "pre_tool.py", timeout: int = 10) -> dict:
    return {
        "type": "command",
        # exec form: no shell, so spaces in "C:\Program Files\..." need no quoting
        "command": str(Path(sys.executable).resolve()),
        "args": [str(PACKAGE_DIR / "hooks" / script), "--project", str(project)],
        "timeout": timeout,
    }


def _is_ours(handler: dict, script: str = "pre_tool.py") -> bool:
    return any(HOOK_MARKER in str(a) and script in str(a) for a in handler.get("args", []))


def merge_settings(settings: dict, project: Path) -> dict:
    """Add (or refresh) our hooks without touching any other hook."""
    for event, (script, matcher, timeout) in OUR_HOOKS.items():
        groups = settings.setdefault("hooks", {}).setdefault(event, [])
        for group in groups:
            group["hooks"] = [h for h in group.get("hooks", []) if not _is_ours(h, script)]
        groups[:] = [g for g in groups if g.get("hooks")]
        group = {"hooks": [hook_entry(project, script, timeout)]}
        if matcher:
            group = {"matcher": matcher, **group}
        groups.append(group)
    return settings


def cmd_install(args) -> int:
    project = Path(args.project_dir).resolve()
    if not project.is_dir():
        print(f"Not a directory: {project}")
        return 1
    path = project / ".claude" / "settings.json"
    settings = {}
    if path.exists():
        text = path.read_text(encoding="utf-8").strip()
        try:
            settings = json.loads(text) if text else {}
        except json.JSONDecodeError as e:
            print(f"{path} is not valid JSON ({e}); not touching it.")
            return 1
    merge_settings(settings, project)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(settings, indent=2) + "\n", encoding="utf-8")
    Graph.for_project(project).close()
    print(f"Installed NotByDefault PreToolUse and UserPromptSubmit hooks in {path}")
    print(f"  python: {sys.executable}")
    return 0


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="python -m notbydefault")
    sub = parser.add_subparsers(dest="command", required=True)

    p = sub.add_parser("init", help="record goals, requirements and constraints")
    p.add_argument("project_dir")
    p.add_argument("--goal")
    p.add_argument("--users")
    p.add_argument("--budget")
    p.add_argument("--region")
    p.add_argument("--team")
    p.add_argument("--no-input", action="store_true", help="don't prompt; skip unanswered")
    p.add_argument("--force", action="store_true", help="replace previous answers")
    p.set_defaults(func=cmd_init)

    p = sub.add_parser("show", help="print the Decision Graph")
    p.add_argument("project_dir")
    p.set_defaults(func=cmd_show)

    p = sub.add_parser("install", help="add the NotByDefault hook to a project")
    p.add_argument("project_dir")
    p.set_defaults(func=cmd_install)

    p = sub.add_parser("check", help="fit-test a decision against the project's constraints")
    p.add_argument("decision_id", type=int)
    p.add_argument("--project", default=".", help="project dir (default: current dir)")
    p.add_argument("--max-cost", type=float, default=1.00,
                   help="stop before spending more than this many USD (default 1.00)")
    p.add_argument("--yes", "-y", action="store_true", help="don't ask for confirmation")
    p.add_argument("--calls-per-user", type=float,
                   help="calls per user per month (asked once, default 30)")
    p.add_argument("--samples", type=int, default=8, help="synthetic inputs to generate")
    p.add_argument("--expand-rounds", type=int, default=1,
                   help="times to add 4 inputs when the verdict is too close to call (default 1)")
    p.set_defaults(func=cmd_check)

    p = sub.add_parser("require", help="add a requirement and mark decisions it makes stale")
    p.add_argument("project_dir")
    p.add_argument("requirement", help='e.g. "EU data residency required"')
    p.set_defaults(func=cmd_require)

    p = sub.add_parser("pivot", help="list pivots, or record the user's choice for one")
    p.add_argument("pivot_id", type=int, nargs="?")
    p.add_argument("--choice", choices=["accepted", "adjusting", "kept"])
    p.add_argument("--project", default=".", help="project dir (default: current dir)")
    p.set_defaults(func=cmd_pivot)

    p = sub.add_parser("label", help="hand-label outputs to measure verifier trust")
    p.add_argument("decision_id", type=int)
    p.add_argument("--project", default=".", help="project dir (default: current dir)")
    p.add_argument("-n", type=int, default=10, help="outputs to label (default 10)")
    p.set_defaults(func=cmd_label)

    args = parser.parse_args(argv)
    return args.func(args)
"""Decision Graph stored in SQLite at <project-dir>/.notbydefault/graph.db."""
from __future__ import annotations

import json
import sqlite3
from datetime import datetime, timezone
from pathlib import Path

NODE_TYPES = {
    "goal", "requirement", "constraint", "decision",
    "evidence", "alternative", "code", "pivot",
}
EDGE_TYPES = {"depends_on", "supported_by", "rejects", "affects", "serves"}

# Edges a decision follows to reach the things it relies on.
DEPENDENCY_EDGES = ("depends_on", "serves", "supported_by")

SCHEMA = """
CREATE TABLE IF NOT EXISTS nodes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    type TEXT NOT NULL,
    label TEXT NOT NULL,
    data_json TEXT NOT NULL DEFAULT '{}',
    created_at TEXT NOT NULL,
    session_id TEXT
);
CREATE TABLE IF NOT EXISTS edges (
    src INTEGER NOT NULL REFERENCES nodes(id) ON DELETE CASCADE,
    dst INTEGER NOT NULL REFERENCES nodes(id) ON DELETE CASCADE,
    type TEXT NOT NULL,
    PRIMARY KEY (src, dst, type)
);
CREATE INDEX IF NOT EXISTS idx_nodes_type ON nodes(type);
CREATE INDEX IF NOT EXISTS idx_edges_dst ON edges(dst);
"""


def db_path(project_dir: str | Path) -> Path:
    return Path(project_dir) / ".notbydefault" / "graph.db"


class Graph:
    def __init__(self, path: str | Path):
        self.path = Path(path)
        self.path.parent.mkdir(parents=True, exist_ok=True)
        # Hooks can fire concurrently for parallel tool calls; wait briefly on locks.
        self.conn = sqlite3.connect(self.path, timeout=2.0)
        self.conn.row_factory = sqlite3.Row
        self.conn.execute("PRAGMA foreign_keys = ON")
        self.conn.executescript(SCHEMA)

    @classmethod
    def for_project(cls, project_dir: str | Path) -> "Graph":
        return cls(db_path(project_dir))

    def close(self) -> None:
        self.conn.close()

    def __enter__(self) -> "Graph":
        return self

    def __exit__(self, *exc) -> None:
        self.close()

    # --- writes -----------------------------------------------------------

    def add_node(self, type: str, label: str, data: dict | None = None,
                 session_id: str | None = None) -> int:
        if type not in NODE_TYPES:
            raise ValueError(f"unknown node type: {type}")
        with self.conn:
            cur = self.conn.execute(
                "INSERT INTO nodes (type, label, data_json, created_at, session_id)"
                " VALUES (?, ?, ?, ?, ?)",
                (type, label, json.dumps(data or {}),
                 datetime.now(timezone.utc).isoformat(timespec="seconds"), session_id),
            )
        return cur.lastrowid

    def add_edge(self, src: int, dst: int, type: str) -> None:
        if type not in EDGE_TYPES:
            raise ValueError(f"unknown edge type: {type}")
        with self.conn:
            self.conn.execute(
                "INSERT OR IGNORE INTO edges (src, dst, type) VALUES (?, ?, ?)",
                (src, dst, type),
            )

    def update_data(self, node_id: int, **fields) -> None:
        node = self.get_node(node_id)
        if node is None:
            raise KeyError(node_id)
        node["data"].update(fields)
        with self.conn:
            self.conn.execute("UPDATE nodes SET data_json = ? WHERE id = ?",
                              (json.dumps(node["data"]), node_id))

    def delete_nodes(self, ids: list[int]) -> None:
        with self.conn:
            self.conn.executemany("DELETE FROM nodes WHERE id = ?", [(i,) for i in ids])

    # --- reads ------------------------------------------------------------

    @staticmethod
    def _row(row: sqlite3.Row) -> dict:
        d = dict(row)
        d["data"] = json.loads(d.pop("data_json") or "{}")
        return d

    def get_node(self, node_id: int) -> dict | None:
        row = self.conn.execute("SELECT * FROM nodes WHERE id = ?", (node_id,)).fetchone()
        return self._row(row) if row else None

    def nodes(self, type: str | None = None) -> list[dict]:
        if type:
            rows = self.conn.execute("SELECT * FROM nodes WHERE type = ? ORDER BY id", (type,))
        else:
            rows = self.conn.execute("SELECT * FROM nodes ORDER BY id")
        return [self._row(r) for r in rows]

    def edges(self) -> list[dict]:
        return [dict(r) for r in self.conn.execute(
            "SELECT src, dst, type FROM edges ORDER BY src, dst, type")]

    def find_node(self, type: str, label: str) -> dict | None:
        row = self.conn.execute(
            "SELECT * FROM nodes WHERE type = ? AND label = ? ORDER BY id LIMIT 1",
            (type, label)).fetchone()
        return self._row(row) if row else None

    def list_decisions(self, status: str | None = None) -> list[dict]:
        decisions = self.nodes("decision")
        if status:
            decisions = [d for d in decisions if d["data"].get("status") == status]
        return decisions

    def neighbors(self, node_id: int, edge_types: tuple[str, ...] | None = None) -> list[dict]:
        """Nodes reached by outgoing edges from node_id (each with its edge type)."""
        sql = ("SELECT n.*, e.type AS edge_type FROM edges e JOIN nodes n ON n.id = e.dst"
               " WHERE e.src = ?")
        params: list = [node_id]
        if edge_types:
            sql += f" AND e.type IN ({','.join('?' * len(edge_types))})"
            params += edge_types
        return [self._row(r) for r in self.conn.execute(sql + " ORDER BY n.id", params)]

    def get_dependencies(self, decision_id: int,
                         edge_types: tuple[str, ...] = DEPENDENCY_EDGES) -> list[dict]:
        """Everything a decision depends on, following edges transitively."""
        seen: dict[int, dict] = {}
        frontier = [decision_id]
        while frontier:
            current = frontier.pop()
            for node in self.neighbors(current, edge_types):
                if node["id"] not in seen and node["id"] != decision_id:
                    seen[node["id"]] = node
                    frontier.append(node["id"])
        return sorted(seen.values(), key=lambda n: n["id"])


def find_affected_code(decision: dict) -> list[str]:
    """Files a decision affects.

    Stub: later this will query Entire Graph for every caller/consumer of the
    chosen service or model. For now it returns the file(s) the tool calls touched.
    """
    data = decision.get("data", {})
    if data.get("files"):
        return list(data["files"])
    return [data["file"]] if data.get("file") else []
"""Stale decisions: `notbydefault require <project> "<new requirement>"`.

Adds a requirement node, turns it into machine-checkable constraints, judges every existing
decision against it (a model, plus documented provider facts that override the model), and
marks the affected decisions stale with the reason and an edge to the requirement.
"""
from __future__ import annotations

import json
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime, timezone
from pathlib import Path

from notbydefault.graph import Graph, db_path, find_affected_code
from notbydefault.llm import LLMError, parse_json

EXTRACT_SYSTEM = ("You turn a product requirement into machine-checkable constraints. "
                  "Answer with one JSON object only.")
EXTRACT_PROMPT = """Requirement: {text}

Return JSON with these keys (null when the requirement says nothing about it):
{{"data_residency": "<region code the data must stay in, e.g. EU, US, UK, or null>",
  "max_monthly_cost_usd": <number or null>,
  "summary": "<the requirement in at most 12 words>"}}"""

JUDGE_SYSTEM = ("You check whether an existing technical decision still holds after a new "
                "requirement. Answer with one JSON object only.")
JUDGE_PROMPT = """New requirement: {text}
Machine-readable constraints: {constraints}

Existing decision #{id}: {label}
Kind: {kind}; category: {category}; status: {status}
What it is used for: {used_for}
Code it affects: {files}
Known facts: {facts}

Is this decision affected, i.e. must it be re-evaluated because of the new requirement?
Return {{"affected": true or false, "reason": "<one line>"}}"""


def constraints_of(node: dict) -> dict:
    return (node.get("data") or {}).get("constraints") or {}


def provider_facts(decision: dict, pricing, catalog: dict) -> tuple[str | None, list[str], str]:
    """(model id, guaranteed residency regions, source) for a model decision; (None, [], "")
    when the decision isn't a model or its provider isn't in the catalog."""
    from notbydefault.fit.candidates import resolve_model_id
    from notbydefault.fit.providers import residency
    if decision["data"].get("kind") != "model":
        return None, [], ""
    try:
        model = resolve_model_id(decision["label"], pricing)
    except LookupError:
        return None, [], ""
    cfg = catalog["providers"].get(model.split(":", 1)[0], {})
    return model, residency(catalog, model), str(cfg.get("data_residency_source", ""))


def residency_violation(decision: dict, constraints: dict, pricing, catalog: dict) -> str | None:
    """A documented reason the decision breaks the residency constraint, or None."""
    region = (constraints.get("data_residency") or "").upper()
    if not region:
        return None
    model, regions, source = provider_facts(decision, pricing, catalog)
    if model and region not in regions:
        where = ", ".join(regions) if regions else "no region guaranteed"
        return (f"{model} runs on {model.split(':', 1)[0]}, which documents data residency: "
                f"{where} (source: {source}); {region} residency is required")
    return None


def judge_decision(caller, model: str, decision: dict, text: str, constraints: dict,
                   facts: str) -> dict:
    data = decision["data"]
    reply = caller.chat(model, [
        {"role": "system", "content": JUDGE_SYSTEM},
        {"role": "user", "content": JUDGE_PROMPT.format(
            text=text, constraints=json.dumps(constraints), id=decision["id"],
            label=decision["label"], kind=data.get("kind"), category=data.get("category"),
            status=data.get("status"),
            used_for=data.get("verdict_summary") or data.get("evidence") or "not recorded",
            files=", ".join(find_affected_code(decision)) or "none recorded",
            facts=facts or "none")},
    ], span="notbydefault.stale_judge", role="stale_judge", max_tokens=1500, json_mode=True,
        focus_area="verification", attrs={"notbydefault.decision_id": decision["id"]})
    out = parse_json(reply.text)
    return {"affected": bool(out.get("affected")), "reason": str(out.get("reason") or "").strip()}


def require(project: Path, text: str, client=None, tracer=None, out=print,
            workers: int = 4) -> int:
    project = Path(project).resolve()
    if not db_path(project).exists():
        out(f"No Decision Graph at {db_path(project)}. Run `init` first.")
        return 1
    from notbydefault.env import load_env
    from notbydefault.fit.evaluate import BudgetExceeded, Caller, SpendGuard
    from notbydefault.fit.providers import ProviderSet, load_catalog, role_model
    from notbydefault.fit.tracing import make_tracer

    if client is None:
        load_env()
        client = ProviderSet(load_catalog(project), cache_dir=project / ".notbydefault" / "cache")
    catalog = client.catalog
    tracer = tracer or make_tracer()
    if hasattr(client, "on_event"):
        client.on_event = tracer.event
    caller = Caller(client, SpendGuard(0.50), tracer)
    model = role_model(catalog, "stale_judge")
    pricing = client.pricing()
    now = datetime.now(timezone.utc).isoformat(timespec="seconds")
    results = []
    with Graph.for_project(project) as g, tracer.root("notbydefault.require",
                                                     {"notbydefault.requirement": text}):
        with tracer.step("extract_constraints", "tool_use",
                         reason="turn the requirement into checks the evaluator can enforce"):
            try:
                reply = caller.chat(model, [{"role": "system", "content": EXTRACT_SYSTEM},
                                            {"role": "user", "content": EXTRACT_PROMPT.format(text=text)}],
                                    span="notbydefault.extract_constraints", role="stale_judge",
                                    max_tokens=1000, json_mode=True, focus_area="tool_use")
                raw = parse_json(reply.text)
            except (LLMError, BudgetExceeded) as e:
                tracer.event("extract_failed", "recovery",
                             f"could not extract constraints ({e}); judging with the text only")
                raw = {}
            constraints = {k: v for k, v in raw.items()
                           if k in ("data_residency", "max_monthly_cost_usd") and v not in (None, "")}
        with tracer.step("add_requirement", "state", reason="record the new requirement"):
            rid = g.add_node("requirement", text, {
                "source": "require", "constraints": constraints, "added_at": now,
                "summary": str(raw.get("summary") or "")})
            tracer.event("requirement_added", "state", f"#{rid}: {text}", requirement_id=rid,
                         constraints=constraints)
        decisions = g.nodes("decision")

        def one(d: dict) -> dict:
            documented = residency_violation(d, constraints, pricing, catalog)
            m, regions, source = provider_facts(d, pricing, catalog)
            facts = (f"provider model {m}; documented data residency: "
                     f"{', '.join(regions) or 'none guaranteed'} ({source})") if m else ""
            try:
                verdict = judge_decision(caller, model, d, text, constraints, facts)
            except (LLMError, BudgetExceeded) as e:
                verdict = {"affected": None, "reason": f"could not judge: {e}"}
                tracer.event("judge_failed", "recovery",
                             f"decision #{d['id']}: {e}; left unchanged", decision_id=d["id"])
            if documented:   # documented facts beat the model's opinion
                verdict = {"affected": True, "reason": documented, "basis": "provider documentation"}
            return {"decision": d, **verdict}

        with tracer.step("judge_decisions", "verification",
                         reason=f"check {len(decisions)} decisions against the new requirement"):
            with ThreadPoolExecutor(max_workers=workers) as pool:
                results = list(pool.map(tracer.bind(one), decisions))
        with tracer.step("mark_stale", "state", reason="mark affected decisions stale"):
            for r in results:
                d = r["decision"]
                if r["affected"]:
                    g.update_data(d["id"], status="stale", stale_reason=r["reason"],
                                  stale_since=now, stale_cause=rid,
                                  status_before_stale=d["data"].get("status"))
                    g.add_edge(d["id"], rid, "depends_on")
                    tracer.event("decision_stale", "planning",
                                 f"#{d['id']} {d['label']}: {r['reason']}", decision_id=d["id"],
                                 requirement_id=rid)
            g.update_data(rid, judged={str(r["decision"]["id"]): {
                "affected": r["affected"], "reason": r["reason"]} for r in results})

    stale = [r for r in results if r["affected"]]
    out(f"Requirement #{rid}: {text}")
    if constraints:
        out(f"  checks: {json.dumps(constraints)}")
    out(f"\n{len(stale)} of {len(results)} decisions are now stale:" if stale
        else f"\nNo decisions are affected ({len(results)} checked).")
    for r in stale:
        d = r["decision"]
        code = ", ".join(find_affected_code(d)) or "no code recorded"
        out(f"  #{d['id']} {d['label']} [{d['data'].get('kind')}/{d['data'].get('category')}]")
        out(f"      why:  {r['reason']}")
        out(f"      code: {code}")
    unclear = [r for r in results if r["affected"] is None]
    for r in unclear:
        out(f"  #{r['decision']['id']} {r['decision']['label']}: {r['reason']}")
    ok = [r for r in results if r["affected"] is False]
    if ok:
        out("\nStill valid:")
        out("\n".join(f"  #{r['decision']['id']} {r['decision']['label']}: {r['reason']}" for r in ok))
    if stale:
        out("\nRe-test a stale model decision with `python -m notbydefault check <id>`; it "
            "applies the new requirement's checks to the candidates.")
    if tracer.trace_id:
        out(f"\nneatlogs trace id: {tracer.trace_id} (workflow notbydefault)")
    tracer.flush()
    return 0

"""Pivot Check: notice when the user changes direction and show what it would undo.

Pipeline for each prompt (hooks/user_prompt.py):
  1. pending choice: if a pivot from this session awaits "switch anyway / adjust / keep plan",
     record the user's answer (no LLM)
  2. pre-filter: cheap regex for change-of-direction phrases; most prompts stop here (no LLM)
  3. confirm: one fast Groq call decides whether it really is a pivot and maps it onto the graph
  4. impact: goals/constraints it conflicts with, decisions it would invalidate (with their
     recorded reasons and evidence) and the code those decisions affect, read from the graph
  5. record a "pivot" node (status: proposed) linked to the affected decisions
"""
from __future__ import annotations

import re
from datetime import datetime, timezone

PIVOT_PHRASES = [
    r"switch(?:ing)? (?:to|from|over)", r"\binstead\b", r"\bactually\b", r"what if we",
    r"let'?s (?:use|go with|try|switch|move)", r"let us use", r"\bdrop(?:ping)?\b",
    r"\breplac(?:e|ing)\b", r"rather than", r"\bgo with\b", r"\bmigrat(?:e|ing) (?:to|from|off)",
    r"\bmove (?:to|off|away from)\b", r"\bchange (?:to|from)\b", r"\bswap\b", r"\bditch\b",
    r"\bscrap\b", r"get rid of", r"\bno longer\b", r"\bforget (?:about )?(?:the|our)\b",
]
PIVOT_RX = re.compile("|".join(PIVOT_PHRASES), re.IGNORECASE)

CHOICES = [  # (status, phrases that answer "switch anyway / adjust / keep plan")
    ("accepted", r"\bswitch anyway\b|\bgo ahead with the (?:switch|change)\b"),
    ("adjusting", r"\badjust(?: the plan)?\b"),
    ("kept", r"\bkeep (?:the )?(?:current )?plan\b|\bkeep (?:it|things) as (?:is|planned)\b"),
]
MAX_CONTEXT = 9000   # Claude Code caps additionalContext at 10,000 characters


STACK_WORDS = re.compile(
    r"\b(models?|llms?|providers?|vendors?|apis?|sdks?|databases?|db|orms?|frameworks?|hosting|"
    r"host|auth(?:entication)?|cloud|backend|stack|architecture|queue|cache|storage|region|"
    r"budget|cost|pricing|plan)\b", re.IGNORECASE)


def stack_terms(graph_labels: list[str] | None = None) -> list[str]:
    """Names that make a prompt about the stack: known services/models + the graph's decisions."""
    from notbydefault.detect import KNOWN_SERVICES, MODEL_PROVIDERS
    names = {label for label, _ in KNOWN_SERVICES.values()}
    names |= {p.rstrip("-/") for p, _ in MODEL_PROVIDERS if len(p.rstrip("-/")) > 2}
    names |= {"openai", "anthropic", "gemini", "groq", "mistral", "llama", "claude", "gpt",
              "postgres", "mysql", "sqlite", "dynamo", "aws", "gcp", "azure", "vertex"}
    names |= {l for l in (graph_labels or []) if l}
    return sorted(names, key=len, reverse=True)


def prefilter(prompt: str, terms: list[str] | None = None) -> list[str]:
    """Change-of-direction phrases, but only in prompts about the stack; [] means no LLM call."""
    phrases = [m.group(0) for m in PIVOT_RX.finditer(prompt or "")]
    if not phrases:
        return []
    low = prompt.lower()
    if STACK_WORDS.search(prompt) or any(
            re.search(rf"(?<![\w]){re.escape(t.lower())}(?![\w])", low)
            for t in (terms or stack_terms())):
        return phrases
    return []


def detect_choice(prompt: str) -> str | None:
    text = (prompt or "").lower()
    for status, rx in CHOICES:
        if re.search(rx, text):
            return status
    return None


# --- graph snapshot sent to the model ------------------------------------------------

def used_for(project_dir, decision_id: int) -> str:
    """What a decision's code does, from the call-site analysis `check` saved (if any)."""
    import json
    from pathlib import Path
    if project_dir is None:
        return ""
    path = Path(project_dir) / ".notbydefault" / "callsites" / f"{decision_id}.json"
    try:
        return str(json.loads(path.read_text(encoding="utf-8")).get("task") or "")
    except (OSError, ValueError):
        return ""


def snapshot(graph, project_dir=None) -> dict:
    """Compact view of goals, requirements, constraints and decisions (ids are graph ids)."""
    def short(text, n=220):
        text = " ".join(str(text or "").split())
        return text if len(text) <= n else text[:n - 1] + "…"

    nodes = {t: graph.nodes(t) for t in ("goal", "requirement", "constraint", "decision")}
    decisions = []
    for d in nodes["decision"]:
        data = d["data"]
        decisions.append({
            "id": d["id"], "label": d["label"], "kind": data.get("kind"),
            "category": data.get("category"), "status": data.get("status"),
            "used_for": short(used_for(project_dir, d["id"]), 160),
            "verdict": short(data.get("verdict_summary")),
            "recommended": data.get("recommended"), "files": data.get("files") or [],
        })
    return {"goals": [{"id": n["id"], "label": n["label"]} for n in nodes["goal"]],
            "requirements_and_constraints": [{"id": n["id"], "label": n["label"]}
                                             for n in nodes["requirement"] + nodes["constraint"]],
            "decisions": decisions}


CONFIRM_SYSTEM = ("You review messages a developer sends to a coding agent. Decide whether the "
                  "message changes the direction of an earlier technical decision. Answer with "
                  "one JSON object only.")

CONFIRM_PROMPT = """The project's Decision Graph:
{graph}

Price facts (list prices; use them for budget conflicts): {prices}

The developer just wrote:
<<<
{prompt}
>>>

A pivot is a change of direction on something already decided: a different model, provider,
database, framework, architecture, or dropping a recorded goal or constraint. Ordinary requests
(fix a bug, add a feature, rename, refactor, explain, "use X instead of Y" for a variable) are
not pivots.

Return JSON:
{{"is_pivot": true or false,
  "change": "<one line: what the developer wants to change, or empty>",
  "decision_ids": [<ids of decisions above this would invalidate>],
  "conflicts": [{{"node_id": <id of a goal/requirement/constraint above>, "why": "<one line>"}}]}}"""


def confirm(caller, model: str, prompt: str, graph_view: dict, prices: str = "none") -> dict:
    """One fast LLM call: is it a pivot, and which graph nodes does it touch?"""
    import json

    from notbydefault.llm import parse_json
    reply = caller.chat(model, [
        {"role": "system", "content": CONFIRM_SYSTEM},
        {"role": "user", "content": CONFIRM_PROMPT.format(
            graph=json.dumps(graph_view, ensure_ascii=False, indent=1), prompt=prompt[:4000],
            prices=prices)},
    ], span="notbydefault.pivot_confirm", role="pivot", max_tokens=1500, json_mode=True,
        extra_body={"reasoning_effort": "low"}, focus_area="verification")
    data = parse_json(reply.text)
    ids = {n["id"] for k in ("goals", "requirements_and_constraints", "decisions")
           for n in graph_view[k]}
    decision_ids = {d["id"] for d in graph_view["decisions"]}
    return {
        "is_pivot": bool(data.get("is_pivot")),
        "change": str(data.get("change") or "").strip(),
        "decision_ids": [int(i) for i in data.get("decision_ids") or []
                         if str(i).lstrip("#").isdigit() and int(str(i).lstrip("#")) in decision_ids],
        "conflicts": [{"node_id": int(str(c.get("node_id")).lstrip("#")), "why": str(c.get("why", ""))}
                      for c in data.get("conflicts") or []
                      if str(c.get("node_id", "")).lstrip("#").isdigit()
                      and int(str(c.get("node_id")).lstrip("#")) in ids],
        "model": model, "latency_s": reply.latency_s, "cached": reply.cached,
    }


# --- impact from the graph (deterministic) -------------------------------------------

def impact(graph, result: dict, project_dir=None, cost: dict | None = None) -> dict:
    from notbydefault.graph import find_affected_code
    conflicts = []
    for c in result["conflicts"]:
        node = graph.get_node(c["node_id"])
        if node:
            conflicts.append({"id": node["id"], "type": node["type"], "label": node["label"],
                              "why": c["why"]})
    decisions = []
    for did in result["decision_ids"]:
        d = graph.get_node(did)
        if not d:
            continue
        data = d["data"]
        evidence = [{"id": e["id"], "label": e["label"],
                     "path": e["data"].get("path") or e["data"].get("url")}
                    for e in graph.neighbors(did, ("supported_by",))]
        decisions.append({
            "id": did, "label": d["label"], "kind": data.get("kind"),
            "status": data.get("status"), "used_for": used_for(project_dir, did),
            "reason": data.get("verdict_summary") or (
                "unreviewed: no fit test yet" if data.get("status") == "unreviewed"
                else data.get("stale_reason") or ""),
            "recommended": data.get("recommended"),
            "evidence": evidence, "code": find_affected_code(d),
        })
    # the budget conflict is computed, not left to the model's judgement
    if cost and cost["over_budget"] and cost["budget_node"]:
        b = cost["budget_node"]
        conflicts = [c for c in conflicts if c["id"] != b["id"]]
        conflicts.insert(0, {"id": b["id"], "type": b["type"], "label": b["label"],
                             "why": f"about ${cost['monthly']:,.0f}/month for {cost['model']} at "
                                    f"list price, {cost['monthly'] / cost['budget']:.0f}x the budget"})
    return {"change": result["change"], "conflicts": conflicts, "decisions": decisions,
            "cost_line": cost_line(cost) if cost else ""}


def render_context(imp: dict, pivot_id: int) -> str:
    """additionalContext for Claude Code (not shown to the user directly)."""
    lines = [f"NotByDefault Pivot Check (pivot #{pivot_id}): the user's message changes an earlier "
             f"decision: {imp['change'] or 'see the message'}."]
    if imp["conflicts"]:
        lines.append("It conflicts with these recorded goals/constraints:")
        lines += [f"- #{c['id']} {c['type']} \"{c['label']}\": {c['why']}" for c in imp["conflicts"]]
    if imp["decisions"]:
        lines.append("It would invalidate these decisions:")
        for d in imp["decisions"]:
            ev = "; ".join(f"#{e['id']} {e['label']}" + (f" ({e['path']})" if e["path"] else "")
                           for e in d["evidence"]) or "none recorded"
            what = f" ({d['used_for'].rstrip('.')})" if d.get("used_for") else ""
            lines.append(f"- #{d['id']} {d['label']}{what} [{d['kind']}, {d['status']}]: {d['reason']} "
                         f"Evidence: {ev}. Code: {', '.join(d['code']) or 'none recorded'}.")
    if imp.get("cost_line"):
        lines.append(imp["cost_line"])
    lines.append(
        "Before doing anything else, show the user a summary of this in at most 6 lines "
        "(the change, the conflicts, the decisions and code affected), then ask them to choose: "
        "(1) switch anyway, (2) adjust the plan, (3) keep the current plan. Do not start the "
        "change until they answer.")
    text = "\n".join(lines)
    return text if len(text) <= MAX_CONTEXT else text[:MAX_CONTEXT - 20] + "\n[truncated]"


def record(graph, prompt: str, imp: dict, session_id: str | None, result: dict) -> int:
    label = (imp["change"] or prompt)[:120]
    pid = graph.add_node("pivot", label, {
        "status": "proposed", "prompt": prompt[:2000], "change": imp["change"],
        "conflicts": imp["conflicts"], "decisions": [d["id"] for d in imp["decisions"]],
        "confirmed_by": result.get("model"),
        "proposed_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
    }, session_id)
    for d in imp["decisions"]:
        graph.add_edge(pid, d["id"], "affects")
    return pid


def pending(graph, session_id: str | None) -> dict | None:
    """The latest proposed pivot of this session, if any."""
    for p in reversed(graph.nodes("pivot")):
        if p["data"].get("status") == "proposed" and (session_id is None or p["session_id"] == session_id):
            return p
    return None


def resolve(graph, pivot: dict, status: str, prompt: str = "") -> list[int]:
    """Record the user's choice. An accepted pivot marks the decisions it affects stale."""
    now = datetime.now(timezone.utc).isoformat(timespec="seconds")
    graph.update_data(pivot["id"], status=status, resolved_at=now, user_answer=prompt[:500])
    stale = []
    if status == "accepted":
        for did in pivot["data"].get("decisions", []):
            d = graph.get_node(did)
            if d and d["type"] == "decision":
                graph.update_data(did, status="stale", stale_since=now,
                                  stale_reason=f"pivot #{pivot['id']} accepted: {pivot['data'].get('change')}",
                                  stale_cause=pivot["id"])
                stale.append(did)
    return stale



# --- cost check (deterministic) ------------------------------------------------------

LOOSE_MODEL = re.compile(
    r"\b(gpt-oss-[\w.-]+|gpt-\d[\w.-]*|chatgpt-[\w.-]+|o[134](?:-mini|-pro)?|claude-[\w.-]+|"
    r"gemini-[\w.-]+|llama-?\d[\w.-]*|mistral-[\w.-]+|deepseek-[\w.-]+|grok-\d[\w.-]*|"
    r"qwen[\d.]*-[\w.-]+)\b", re.IGNORECASE)
DEFAULT_TOKENS = (1000, 300)   # per-call assumption when nothing was measured
OPENROUTER_TTL_S = 24 * 3600


def named_models(prompt: str) -> list[str]:
    seen: dict[str, None] = {}
    for m in LOOSE_MODEL.finditer(prompt or ""):
        seen.setdefault(m.group(1).lower().rstrip(".,"), None)
    return list(seen)


def _openrouter_models(project_dir) -> list[dict]:
    """OpenRouter's public model list (no key needed), cached on disk for a day."""
    import json
    import time
    from pathlib import Path
    from notbydefault.openrouter import fetch_models
    cache = Path(project_dir) / ".notbydefault" / "cache" / "openrouter-models.json"
    try:
        if cache.exists() and time.time() - cache.stat().st_mtime < OPENROUTER_TTL_S:
            return json.loads(cache.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        pass
    models = fetch_models(timeout=5)
    cache.parent.mkdir(parents=True, exist_ok=True)
    cache.write_text(json.dumps(models), encoding="utf-8")
    return models


def list_price(model: str, client, project_dir) -> dict | None:
    """{"model", "in", "out" (USD per token), "source", "fetched"} or None."""
    from datetime import datetime, timezone
    from notbydefault.fit.candidates import resolve_model_id
    try:
        mid = resolve_model_id(model, client.pricing())
        pr = client.pricing().price(mid)
        return {"model": mid, "in": pr.prompt, "out": pr.completion,
                "source": pr.source_url, "fetched": pr.fetched_at}
    except (LookupError, Exception):
        pass
    try:
        models = _openrouter_models(project_dir)
    except Exception:
        return None
    exact = [m for m in models if m["id"].split("/")[-1].lower() == model.lower()]
    if not exact:
        return None
    m = min(exact, key=lambda m: len(m["id"]))
    try:
        return {"model": m["id"], "in": float(m["pricing"]["prompt"]),
                "out": float(m["pricing"]["completion"]),
                "source": "https://openrouter.ai/api/v1/models",
                "fetched": datetime.now(timezone.utc).date().isoformat()}
    except (KeyError, TypeError, ValueError):
        return None


def volume(graph) -> dict:
    """Users, calls per user per month and monthly budget from the graph (None if unknown)."""
    from notbydefault.fit.stats import parse_number
    out = {"users": None, "calls_per_user": None, "budget": None, "budget_node": None}
    for n in graph.nodes("requirement") + graph.nodes("constraint"):
        key, value = n["data"].get("key"), n["data"].get("value")
        if key == "users":
            out["users"] = parse_number(str(value))
        elif key == "calls_per_user":
            out["calls_per_user"] = parse_number(str(value))
        elif key == "budget":
            out["budget"], out["budget_node"] = parse_number(str(value)), n
    return out


def tokens_per_call(graph, project_dir, decision_ids: list[int]) -> tuple[int, int, str]:
    """Measured average tokens per call of an affected decision's current model, or the default."""
    import json
    from pathlib import Path
    for did in decision_ids:
        d = graph.get_node(did)
        res = d and d["data"].get("results")
        if not res or project_dir is None:
            continue
        try:
            data = json.loads((Path(project_dir) / res).read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        chosen = data.get("config", {}).get("chosen")
        rows = [r for r in data.get("rows", []) if r.get("model") == chosen
                and r.get("setup") == "alone" and not r.get("error")]
        if rows:
            tin = round(sum(r["input_tokens"] for r in rows) / len(rows))
            tout = round(sum(r["output_tokens"] for r in rows) / len(rows))
            return tin, tout, f"measured on decision #{did}'s fit test ({res})"
    return DEFAULT_TOKENS[0], DEFAULT_TOKENS[1], (
        f"assumed {DEFAULT_TOKENS[0]} input + {DEFAULT_TOKENS[1]} output tokens per call "
        "(no fit test measured yet)")


def price_facts(prompt: str, client, project_dir) -> list[dict]:
    return [p for p in (list_price(m, client, project_dir) for m in named_models(prompt)) if p]


def cost_check(graph, project_dir, prices: list[dict], decision_ids: list[int]) -> dict | None:
    """Projected monthly cost of the model the user wants, against the recorded budget."""
    if not prices:
        return None
    v = volume(graph)
    if not (v["users"] and v["calls_per_user"]):
        return None
    tin, tout, basis = tokens_per_call(graph, project_dir, decision_ids)
    calls = v["users"] * v["calls_per_user"]
    p = prices[0]
    monthly = calls * (tin * p["in"] + tout * p["out"])
    return {"model": p["model"], "monthly": monthly, "calls": calls, "tokens_in": tin,
            "tokens_out": tout, "basis": basis, "budget": v["budget"],
            "budget_node": v["budget_node"], "price": p,
            "over_budget": v["budget"] is not None and monthly > v["budget"]}


def cost_line(c: dict) -> str:
    p = c["price"]
    line = (f"Cost check: {c['model']} at list price (${p['in'] * 1e6:.2f}/M input, "
            f"${p['out'] * 1e6:.2f}/M output; {p['source']}, {p['fetched']}) x "
            f"{c['calls']:,.0f} calls/month x {c['tokens_in']} in + {c['tokens_out']} out tokens "
            f"({c['basis']}) = about ${c['monthly']:,.0f}/month")
    if c["budget"] is not None:
        line += (f" vs a ${c['budget']:,.0f}/month budget"
                 + (" (OVER BUDGET)" if c["over_budget"] else ""))
    return line + "."
"""OpenAI-compatible chat client shared by every provider (Groq, Gemini, OpenRouter, ...)."""
from __future__ import annotations

import json
import re
import time
import urllib.error
import urllib.request
from dataclasses import dataclass, field

MAX_INLINE_WAIT_S = 90   # a 429 asking us to wait longer than this is treated as a daily limit
MAX_TIMEOUT_RETRIES = 1  # timeouts are retried once (a model that hangs twice is reported)


class LLMError(RuntimeError):
    pass


class ModelUnavailable(LLMError):
    """The model can't be used with this key at all (HTTP 404/403, or a free-tier limit of 0)."""

    def __init__(self, provider: str, model: str, detail: str):
        self.provider, self.model, self.detail = provider, model, detail
        super().__init__(f"{provider}:{model} is unavailable: {detail}")


class DailyLimitReached(RuntimeError):
    """A quota that won't reset within minutes (daily limit, or not on the free tier)."""

    def __init__(self, provider: str, model: str, detail: str, resets: str = ""):
        self.provider, self.model, self.detail, self.resets = provider, model, detail, resets
        super().__init__(f"{provider}:{model}: {detail}" + (f" (resets {resets})" if resets else ""))


@dataclass
class Price:
    """USD per token (list price)."""
    prompt: float
    completion: float
    source_url: str = ""
    fetched_at: str = ""

    def cost(self, input_tokens: float, output_tokens: float) -> float:
        return input_tokens * self.prompt + output_tokens * self.completion


@dataclass
class Pricing:
    prices: dict[str, Price]
    source_url: str          # human-readable summary of where prices came from
    fetched_at: str
    models: list[dict] = field(default_factory=list)

    def price(self, model: str) -> Price:
        if model not in self.prices:
            raise LLMError(f"no price for model {model!r} ({self.source_url})")
        return self.prices[model]


@dataclass
class ChatResult:
    model: str
    text: str
    input_tokens: int
    output_tokens: int
    latency_s: float
    cost: float
    finish_reason: str | None = None
    reported_cost: float | None = None
    cached: bool = False


def _duration_s(text: str | None) -> float | None:
    """'2.5', '29954s', '1m26.4s', '7.66s' -> seconds."""
    if not text:
        return None
    try:
        return float(text)
    except ValueError:
        pass
    total, found = 0.0, False
    for value, unit in re.findall(r"([\d.]+)(ms|h|m|s)", text):
        found = True
        total += float(value) * {"ms": 0.001, "s": 1, "m": 60, "h": 3600}[unit]
    return total if found else None


def classify_429(body: str, headers) -> tuple[str, float | None]:
    """('minute' | 'daily' | 'unavailable', wait_s). 'unavailable' = free-tier limit of 0."""
    wait = _duration_s(headers.get("retry-after") if headers else None)
    try:
        data = json.loads(body)
    except json.JSONDecodeError:
        data = {}
    err = (data[0] if isinstance(data, list) and data else data).get("error", {}) \
        if isinstance(data, (list, dict)) else {}
    message = str(err.get("message", body))
    for detail in err.get("details", []) if isinstance(err, dict) else []:
        if "RetryInfo" in str(detail.get("@type", "")):
            wait = _duration_s(detail.get("retryDelay")) or wait
    quota_ids = " ".join(v.get("quotaId", "") for d in err.get("details", []) if isinstance(d, dict)
                         for v in d.get("violations", []) or []) if isinstance(err, dict) else ""
    if re.search(r"limit:\s*0\b", message):                  # not on the free tier at all
        return "unavailable", wait
    daily = (
        re.search(r"per ?day|PerDay|\b(RPD|TPD)\b", message + " " + quota_ids, re.I) is not None
        or (wait is not None and wait > MAX_INLINE_WAIT_S)
    )
    return ("daily" if daily else "minute"), wait


class OpenAICompatClient:
    """POST {base_url}/chat/completions with bearer auth; retries 429/5xx with backoff."""

    def __init__(self, provider: str, base_url: str, api_key: str, timeout: float = 120.0,
                 retries: int = 6, extra_headers: dict | None = None, sleep=time.sleep,
                 on_event=None):
        self.provider = provider
        self.base_url = base_url.rstrip("/")
        self.api_key = api_key
        self.timeout = timeout
        self.retries = retries
        self.extra_headers = extra_headers or {}
        self.sleep = sleep
        self.on_event = on_event   # on_event(name, focus_area, reason, **attrs) for recoveries

    def _emit(self, name: str, reason: str, **attrs) -> None:
        if self.on_event:
            try:
                self.on_event(name, "recovery", reason, provider=self.provider, **attrs)
            except Exception:
                pass

    def _post(self, path: str, body: dict, model: str) -> dict:
        headers = {"Content-Type": "application/json", "User-Agent": "notbydefault",
                   "Authorization": f"Bearer {self.api_key}", **self.extra_headers}
        data = json.dumps(body).encode()
        last: Exception | None = None
        timeouts = 0
        for attempt in range(self.retries):
            req = urllib.request.Request(f"{self.base_url}{path}", data=data, headers=headers,
                                         method="POST")
            try:
                with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                    return json.loads(resp.read().decode("utf-8"))
            except urllib.error.HTTPError as e:
                detail = e.read().decode("utf-8", errors="replace")
                if e.code == 429:
                    kind, wait = classify_429(detail, e.headers)
                    if kind == "unavailable":
                        raise ModelUnavailable(self.provider, model, _short(detail))
                    if kind == "daily":
                        raise DailyLimitReached(self.provider, model, _short(detail),
                                                _reset_hint(self.provider, e.headers, wait))
                    pause = min(MAX_INLINE_WAIT_S, (wait or 2 ** attempt) + 0.5)
                    self._emit("rate_limit_backoff",
                               f"HTTP 429 per-minute limit on {model}; waiting {pause:.1f}s "
                               f"(attempt {attempt + 1}/{self.retries})",
                               model=model, wait_s=pause, attempt=attempt + 1)
                    last = LLMError(f"{self.provider}:{model}: rate limited (HTTP 429)")
                    self.sleep(pause)
                    continue
                if e.code in (402, 403, 404):   # 402: model needs paid credits on this key
                    raise ModelUnavailable(self.provider, model, f"HTTP {e.code}: {_short(detail)}")
                last = LLMError(f"{self.provider}:{model}: HTTP {e.code}: {_short(detail)}")
                if e.code not in (408, 500, 502, 503, 504):
                    break
            except (urllib.error.URLError, TimeoutError) as e:
                last = LLMError(f"{self.provider}:{model}: network error: {e}")
                if isinstance(e, TimeoutError) or "timed out" in str(e):
                    timeouts += 1
                    if timeouts > MAX_TIMEOUT_RETRIES:   # a hung model shouldn't stall the run
                        break
            pause = min(30, 2 ** attempt)
            if attempt + 1 < self.retries:
                self._emit("retry_failed_call", f"{last}; retrying in {pause}s "
                           f"(attempt {attempt + 1}/{self.retries})",
                           model=model, wait_s=pause, attempt=attempt + 1)
            self.sleep(pause)
        raise last  # type: ignore[misc]

    def complete(self, model: str, messages: list[dict], temperature: float = 0.0,
                 max_tokens: int = 1024, json_mode: bool = False,
                 extra_body: dict | None = None) -> tuple[dict, float]:
        """Raw response JSON and latency in seconds."""
        body: dict = {"model": model, "messages": messages, "temperature": temperature,
                      "max_tokens": max_tokens, **(extra_body or {})}
        if json_mode:
            body["response_format"] = {"type": "json_object"}
        start = time.perf_counter()
        data = self._post("/chat/completions", body, model)
        if isinstance(data, list):  # Gemini sometimes wraps responses in a list
            data = data[0] if data else {}
        if "error" in data:
            raise LLMError(f"{self.provider}:{model}: {data['error']}")
        return data, time.perf_counter() - start


def parse_usage(data: dict) -> tuple[str, int, int, str | None, float | None]:
    choice = (data.get("choices") or [{}])[0]
    usage = data.get("usage") or {}
    return ((choice.get("message") or {}).get("content") or "",
            int(usage.get("prompt_tokens") or 0), int(usage.get("completion_tokens") or 0),
            choice.get("finish_reason"), usage.get("cost"))


def _short(text: str, n: int = 300) -> str:
    return " ".join(text.split())[:n]


def _reset_hint(provider: str, headers, wait: float | None) -> str:
    if provider == "gemini":
        return "at midnight Pacific time"
    reset = headers.get("x-ratelimit-reset-requests") if headers else None
    if reset:
        return f"in {reset}"
    return f"in ~{wait / 3600:.1f} h" if wait else ""


def parse_json(text: str):
    """Parse a JSON object/array from an LLM reply, tolerating code fences and chatter."""
    text = text.strip()
    if text.startswith("```"):
        text = text.split("\n", 1)[1] if "\n" in text else text
        text = text.rsplit("```", 1)[0]
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        pass
    for open_, close in (("{", "}"), ("[", "]")):
        i, j = text.find(open_), text.rfind(close)
        if i != -1 and j > i:
            try:
                return json.loads(text[i:j + 1])
            except json.JSONDecodeError:
                continue
    raise LLMError(f"could not parse JSON from model reply: {text[:200]!r}")
"""Decide whether a tool call is a decision moment (a consequential stack choice)."""
from __future__ import annotations

import re
import shlex
from dataclasses import asdict, dataclass
from pathlib import Path

# --- editable knowledge ------------------------------------------------------
# package name -> (what was chosen, category). Names are npm or PyPI names,
# compared lo

# --- packages -----------------------------------------------------------------

def normalize_package(token: str, ecosystem: str) -> str:
    token = token.strip().strip("'\"")
    if ecosystem == "npm":
        # keep a leading @scope, drop "@version"
        m = re.match(r"(@[^@/\s]+/[^@\s]+|[^@\s]+)", token)
        name = m.group(1) if m else token
    else:
        name = re.split(r"[<>=!~\[;@\s]", token, maxsplit=1)[0]
    return name.lower().replace("_", "-")


def lookup_service(package: str) -> tuple[str, str] | None:
    if package in KNOWN_SERVICES:
        return KNOWN_SERVICES[package]
    for scope, hit in KNOWN_SCOPES.items():
        if package.startswith(scope):
            return hit
    return None


def _services_from_packages(packages: list[str], source: str,
                            file: str | None) -> list[Detection]:
    found: dict[str, Detection] = {}
    for pkg in packages:
        hit = lookup_service(pkg)
        if not hit:
            continue
        chosen, category = hit
        if chosen in found:
            found[chosen].evidence += f", {pkg}"
        else:
            found[chosen] = Detection("service", chosen, category, pkg, source, file)
    return list(found.values())


# --- shell commands -----------------------------------------------------------

# (command prefix tokens, ecosystem, manifest the install writes to)
INSTALLERS: list[tuple[tuple[str, ...], str, str | None]] = [
    (("npm", "install"), "npm", "package.json"),
    (("npm", "i"), "npm", "package.json"),
    (("npm", "add"), "npm", "package.json"),
    (("yarn", "add"), "npm", "package.json"),
    (("pnpm", "add"), "npm", "package.json"),
    (("pnpm", "install"), "npm", "package.json"),
    (("pnpm", "i"), "npm", "package.json"),
    (("bun", "add"), "npm", "package.json"),
    (("bun", "install"), "npm", "package.json"),
    (("bun", "i"), "npm", "package.json"),
    (("pip", "install"), "py", None),
    (("pip3", "install"), "py", None),
    (("uv", "pip", "install"), "py", None),
    (("uv", "add"), "py", "pyproject.toml"),
    (("poetry", "add"), "py", "pyproject.toml"),
    (("pipenv", "install"), "py", "Pipfile"),
]
# flags whose next token is a value, not a package
VALUE_FLAGS = {"-r", "--requirement", "-c", "--constraint", "-e", "--editable",
               "-i", "--index-url", "--extra-index-url", "-t", "--target",
               "--prefix", "--registry", "-G", "--group", "--python", "-p"}


def _tokens(segment: str) -> list[str]:
    # posix=False keeps Windows backslashes intact; strip the quotes it leaves on.
    try:
        tokens = shlex.split(segment, posix=False)
    except ValueError:
        tokens = segment.split()
    return [t.strip("'\"") for t in tokens]


def _strip_launcher(tokens: list[str]) -> list[str]:
    """Turn `python -m pip install x` / `py -3.12 -m pip ...` / `sudo pip` into `pip ...`."""
    while tokens and (tokens[0] in {"sudo", "&"} or re.fullmatch(r"\w+=\S*", tokens[0])):
        tokens = tokens[1:]
    if tokens:
        exe = Path(tokens[0].replace("\\", "/")).name.lower().removesuffix(".exe")
        tokens = [exe, *tokens[1:]]
    if tokens and re.fullmatch(r"python[\d.]*|py", tokens[0]):
        rest = [t for t in tokens[1:] if not re.fullmatch(r"-\d[\d.]*", t)]
        if len(rest) >= 2 and rest[0] == "-m":
            return rest[1:]
    if tokens and tokens[0] in {"npx", "bunx"}:  # `npx prisma init` runs, doesn't install
        return []
    return tokens


def packages_from_command(command: str) -> list[tuple[str, str, str | None]]:
    """(package, ecosystem, manifest) for each package an install command adds."""
    results = []
    for segment in re.split(r"&&|\|\||[;|\n]", command):
        tokens = _strip_launcher(_tokens(segment.strip()))
        for prefix, eco, manifest in INSTALLERS:
            if tuple(tokens[: len(prefix)]) != prefix:
                continue
            skip = False
            for tok in tokens[len(prefix):]:
                if skip:
                    skip = False
                    continue
                if tok in VALUE_FLAGS:
                    skip = True
                    continue
                if tok.startswith("-") or tok.startswith(("./", ".\\", "/")) or tok == ".":
                    continue
                results.append((normalize_package(tok, eco), eco, manifest))
            break
    return results


def detect_shell(command: str, cwd: str | None) -> list[Detection]:
    by_manifest: dict[str | None, list[str]] = {}
    for pkg, _eco, manifest in packages_from_command(command):
        by_manifest.setdefault(manifest, []).append(pkg)
    detections: list[Detection] = []
    for manifest, packages in by_manifest.items():
        file = str(Path(cwd, manifest)) if (cwd and manifest) else manifest
        detections += _services_from_packages(packages, "shell", file)
    return _dedupe(detections)


# --- file edits ---------------------------------------------------------------

def is_manifest(path: str) -> bool:
    name = Path(path.replace("\\", "/")).name
    return name in MANIFEST_NAMES or re.fullmatch(r"requirements[\w.-]*\.txt", name) is not None


def dependency_names(path: str, text: str) -> set[str]:
    name = Path(path.replace("\\", "/")).name
    if name == "package.json":
        return {normalize_package(n, "npm")
                for n in re.findall(r'"(@?[\w.\-/]+)"\s*:\s*"[^"]*"', text)}
    names: set[str] = set()
    for line in text.splitlines():
        line = line.split("#", 1)[0].strip()
        if not line:
            continue
        if name.endswith(".txt"):
            m = re.match(r"([A-Za-z0-9][\w.\-]*)", line)
            if m:
                names.add(normalize_package(m.group(1), "py"))
        else:  # pyproject.toml / Pipfile: quoted PEP 508 strings and `name = "..."` tables
            for q in re.findall(r"""["']([A-Za-z0-9][\w.\-]*)\s*(?:[<>=!~\[;@][^"']*)?["']""", line):
                names.add(normalize_package(q, "py"))
            m = re.match(r"([A-Za-z0-9][\w.\-]*)\s*=", line)
            if m:
                names.add(normalize_package(m.group(1), "py"))
    return names


def model_ids(text: str) -> list[str]:
    seen: dict[str, None] = {}
    for m in MODEL_ID.finditer(text):
        seen.setdefault(m.group(1), None)
    return list(seen)


def model_provider(model: str) -> str:
    low = model.lower()
    for prefix, provider in MODEL_PROVIDERS:
        if low.startswith(prefix):
            return provider
    return "unknown"


def _read(path: str) -> str | None:
    try:
        p = Path(path)
        if p.is_file() and p.stat().st_size <= MAX_FILE_BYTES:
            return p.read_text(encoding="utf-8", errors="replace")
    except OSError:
        pass
    return None


def detect_file_change(path: str, old_text: str, new_text: str) -> list[Detection]:
    """Detections for text `new_text` written into `path` that previously held `old_text`."""
    detections: list[Detection] = []
    if is_manifest(path):
        added = dependency_names(path, new_text) - dependency_names(path, old_text)
        detections += _services_from_packages(sorted(added), "manifest", path)
    before = {m.lower() for m in model_ids(old_text)}
    for model in model_ids(new_text):
        if model.lower() not in before:
            detections.append(Detection("model", model, "ai-model",
                                        f"{model_provider(model)} model literal", "code", path))
    return _dedupe(detections)


def detect_file_tool(tool_name: str, tool_input: dict) -> list[Detection]:
    path = tool_input.get("file_path") or ""
    if not path:
        return []
    current = _read(path)
    if tool_name == "Write":
        return detect_file_change(path, current or "", tool_input.get("content") or "")
    edits = tool_input.get("edits") or [tool_input]  # MultiEdit-style or single Edit
    old = current if current is not None else "\n".join(e.get("old_string") or "" for e in edits)
    new = "\n".join(e.get("new_string") or "" for e in edits)
    return detect_file_change(path, old, new)


# --- entry point --------------------------------------------------------------

def _dedupe(detections: list[Detection]) -> list[Detection]:
    seen: dict[tuple[str, str], Detection] = {}
    for d in detections:
        seen.setdefault((d.kind, d.chosen.lower()), d)
    return list(seen.values())


def detect(event: dict) -> list[Detection]:
    """Decision moments in a PreToolUse event. Empty list means nothing to flag."""
    tool_name = event.get("tool_name") or ""
    tool_input = event.get("tool_input") or {}
    if tool_name in SHELL_TOOLS:
        return detect_shell(tool_input.get("command") or "", event.get("cwd"))
    if tool_name in FILE_TOOLS:
        return detect_file_tool(tool_name, tool_input)
    return []
